    const parts = trimmed.split(' | ').map((p) => p.trim());
    // Check if it's a literal union (all parts are string literals)
    const allLiterals = parts.every((p) => p.startsWith('"') || p.startsWith("'"));
    if (allLiterals) {
      return {
        name: 'union',
        value: parts.map((p) => ({
          name: 'literal' as const,
          value: p.replace(/^["']|["']$/g, ''),
        })),
      };
    }
